const int moveY[] = {0, 0, 1, -1};

int sizeN, maxT, startXCoord, startYCoord;
string gridLab[20], gridSci[20];
int memoDP[12][12][12][12][62];
int capGraph[250][250], parentNode[250];
int distMap[20][20], visitedMap[20][20];

inline bool isAccessible(int x, int y){
	return 0 <= x && x < sizeN && 0 <= y && y < sizeN && gridLab[x][y] != 'Y' && gridLab[x][y] != 'Z';
}

void initializeDistances(){
	memset(distMap, 0x3f, sizeof(distMap));
	memset(visitedMap, 0, sizeof(visitedMap));
	distMap[startXCoord][startYCoord] = 0;
	visitedMap[startXCoord][startYCoord] = 1;
	queue<int> qx, qy;
	qx.push(startXCoord);
	qy.push(startYCoord);
	while(!qx.empty()){
		int x = qx.front(); qx.pop();
		int y = qy.front(); qy.pop();
		for(int dirIdx = 0; dirIdx < 4; dirIdx++){
			int nx = x + moveX[dirIdx];
			int ny = y + moveY[dirIdx];
			if(isAccessible(nx, ny) && !visitedMap[nx][ny]){
				distMap[nx][ny] = distMap[x][y] + 1;
				visitedMap[nx][ny] = 1;
				qx.push(nx);
				qy.push(ny);
			}
		}
	}
}

int findPath(int xA, int yA, int xB, int yB, int stepCount){
	if(stepCount > maxT)return 0;
	int &res = memoDP[xA][yA][xB][yB][stepCount];
	if(res != -1)return res;
	if(xA == xB && yA == yB)return distMap[xA][yA] >= stepCount;
	if(distMap[xA][yA] <= stepCount)return res = 0;
	for(int dirIdx = 0; dirIdx < 4; dirIdx++){
		int nx = xA + moveX[dirIdx];
		int ny = yA + moveY[dirIdx];
		if(isAccessible(nx, ny) && findPath(nx, ny, xB, yB, stepCount + 1))return res = 1;
	}
	return res = 0;
}

bool runFlow(int s, int t){
	memset(parentNode, -1, sizeof(parentNode));
	parentNode[s] = -2;
	queue<int> q;
	q.push(s);
	while(!q.empty()){
		int v = q.front(); q.pop();
		for(int i = s; i <= t; i++){
			if(parentNode[i] == -1 && capGraph[v][i] > 0){
				parentNode[i] = v;
				q.push(i);
			}
		}
	}
	return parentNode[t] != -1;
}

