	}
	vector<pair<int, int>> points;
	vector<int> loadCapacities, supplyCapacities;
	for(int i = 0; i < sizeN; i++){
		for(int j = 0; j < sizeN; j++){
			if(gridSci[i][j] == 'Z'){
				startXCoord = i;
				startYCoord = j;
