			}
		}
	}
	int m = (int)points.size();
	memset(capGraph, 0, sizeof(capGraph));
	for(int i = 0; i < m; i++){
		capGraph[0][i + 1] = supplyCapacities[i];
		capGraph[m + 1 + i][2 * m + 1] = loadCapacities[i];
	}
	initializeDistances();
	memset(memoDP, -1, sizeof(memoDP));
	for(int i = 0; i < m; i++){
		for(int j = 0; j < m; j++){
			if(findPath(points[i].first, points[i].second, points[j].first, points[j].second, 0)){
				capGraph[i + 1][m + 1 + j] = 1000;
			}
		}
	}
	int totalFlow = 0;
	while(runFlow(0, 2 * m + 1)){
		int current = 2 * m + 1;
		int flowVal = 1e6;
		while(parentNode[current] >= 0){
			flowVal = min(flowVal, capGraph[parentNode[current]][current]);
			current = parentNode[current];
		}
		current = 2 * m + 1;
		while(parentNode[current] >= 0){
			capGraph[parentNode[current]][current] -= flowVal;
